import{_ as t,o as a,c as r,a5 as s}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Sequence Flow — Create Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-12-create-workspace/sequence-flow.md","filePath":"feature/agency-workspace/3-4-12-create-workspace/sequence-flow.md"}'),i={name:"feature/agency-workspace/3-4-12-create-workspace/sequence-flow.md"};function o(n,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="sequence-flow-—-create-workspace" tabindex="-1">Sequence Flow — Create Workspace <a class="header-anchor" href="#sequence-flow-—-create-workspace" aria-label="Permalink to &quot;Sequence Flow — Create Workspace&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.12). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly. It does not restate business rules — see <code>spec.md</code> for those. &gt; &gt; Updated: 2026-09-23.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Client</strong> — a member of the Agency, and the creator of the Workspace.</li><li><strong>System</strong> — the application service handling the request.</li><li><strong>Database</strong> — the persistent store holding Workspace, membership, Agency membership, and user records.</li><li><strong>Notification service</strong> — dispatches any transactional email triggered during creation.</li></ul><hr><h2 id="flow-a-—-create-a-workspace-without-member-assignment" tabindex="-1">Flow A — Create a Workspace without member assignment <a class="header-anchor" href="#flow-a-—-create-a-workspace-without-member-assignment" aria-label="Permalink to &quot;Flow A — Create a Workspace without member assignment&quot;">​</a></h2><ol><li>Client → System: open the Create Workspace form inside an Agency and fill in the name, the Agency, and any optional fields.</li><li>System: validate the request — <code>name</code> empty or <code>agencyId</code> missing is rejected with 400 <code>VALIDATION_ERROR</code>.</li><li>System → Database: read the caller&#39;s Agency membership for the target Agency; a missing membership is rejected with 403 <code>NOT_AGENCY_OWNER</code>.</li><li>System → Database: insert the Workspace row, with default settings and the caller recorded as its creator.</li><li>System → Database: insert the creator&#39;s membership row with role MANAGER and active status, in the same transaction.</li><li>Database → System: the created Workspace.</li><li>System → Client: the created Workspace summary.</li><li>Client: navigate into the new Workspace.</li></ol><h2 id="flow-b-—-create-a-workspace-with-member-assignment-and-manager-transfer" tabindex="-1">Flow B — Create a Workspace with member assignment and MANAGER transfer <a class="header-anchor" href="#flow-b-—-create-a-workspace-with-member-assignment-and-manager-transfer" aria-label="Permalink to &quot;Flow B — Create a Workspace with member assignment and MANAGER transfer&quot;">​</a></h2><ol><li>Client → System: fill in the form and add assignment entries, one of them naming a different user as MANAGER.</li><li>System: validate the request as in Flow A.</li><li>System → Database: read the caller&#39;s Agency membership; a missing membership is rejected with 403 <code>NOT_AGENCY_OWNER</code>.</li><li>System: note that another user was chosen as MANAGER, so the creator will not hold that role.</li><li>System → Database: insert the Workspace row.</li><li>System → Database: insert the creator&#39;s membership row with role CREATOR.</li><li>System: process each assignment entry: <ul><li>System → Database: read the Agency membership of the entry&#39;s user; a missing membership is rejected with 403 <code>NOT_AGENCY_MEMBER</code>.</li><li>System → Database: check for an existing active membership for that user in the Workspace; if one exists, skip the entry without error.</li><li>System → Database (when the entry requests MANAGER): count the active MANAGERs in the Workspace; a count above zero is rejected with 409 <code>MANAGER_ALREADY_ASSIGNED</code>.</li><li>System → Database: read the user record; a missing user raises <code>USER_NOT_FOUND</code>.</li><li>System → Database: insert the membership row for that entry.</li></ul></li><li>System → Client: the created Workspace summary.</li><li>Client: navigate into the new Workspace, whose MANAGER is the designated user.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>Status</th><th>Error code</th></tr></thead><tbody><tr><td>Create</td><td><code>name</code> empty</td><td>400</td><td><code>VALIDATION_ERROR</code></td></tr><tr><td>Create</td><td><code>agencyId</code> missing</td><td>400</td><td><code>VALIDATION_ERROR</code></td></tr><tr><td>Create</td><td>Caller is not a member of the target Agency</td><td>403</td><td><code>NOT_AGENCY_OWNER</code></td></tr><tr><td>Create (assignment)</td><td>An entry&#39;s user is not an Agency member</td><td>403</td><td><code>NOT_AGENCY_MEMBER</code></td></tr><tr><td>Create (assignment)</td><td>An entry requests MANAGER while the Workspace already has an active MANAGER</td><td>409</td><td><code>MANAGER_ALREADY_ASSIGNED</code></td></tr><tr><td>Create (assignment)</td><td>An entry&#39;s user does not exist in the user records</td><td>—</td><td><code>USER_NOT_FOUND</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The Workspace row and the creator&#39;s membership row are written in a single transaction; assignment entries are applied immediately afterwards.</li><li>The creator is MANAGER by default and is demoted to CREATOR when the MANAGER role is handed to another user, so the Workspace always ends up with exactly one active MANAGER.</li><li>An assignment entry for a user who is already an active member of the new Workspace is skipped without error.</li></ul>',14)])])}const u=t(i,[["render",o]]);export{p as __pageData,u as default};
